namespace RonSijm.FluidHumidifier.Factories.Batch;

public class QuotaShareFactory(string resourceName = null, Action<Humidifier.Batch.QuotaShare> factoryAction = null) : ResourceFactory<Humidifier.Batch.QuotaShare>(resourceName)
{

    internal List<InnerQuotaShareQuotaShareCapacityLimitFactory> CapacityLimitsFactories { get; set; } = [];

    internal InnerQuotaShareQuotaSharePreemptionConfigurationFactory PreemptionConfigurationFactory { get; set; }

    internal InnerQuotaShareQuotaShareResourceSharingConfigurationFactory ResourceSharingConfigurationFactory { get; set; }

    protected override Humidifier.Batch.QuotaShare Create()
    {
        var quotaShareResult = CreateQuotaShare();
        factoryAction?.Invoke(quotaShareResult);

        return quotaShareResult;
    }

    private Humidifier.Batch.QuotaShare CreateQuotaShare()
    {
        var quotaShareResult = new Humidifier.Batch.QuotaShare
        {
            GivenName = InputResourceName,
        };

        return quotaShareResult;
    }
    public override void CreateChildren(Humidifier.Batch.QuotaShare result)
    {
        base.CreateChildren(result);

        result.CapacityLimits = CapacityLimitsFactories.Any() ? CapacityLimitsFactories.Select(x => x.Build()).ToList() : null;
        result.PreemptionConfiguration ??= PreemptionConfigurationFactory?.Build();
        result.ResourceSharingConfiguration ??= ResourceSharingConfigurationFactory?.Build();
    }

} // End Of Class

